import { Formik, Form, Field, ErrorMessage } from "formik";
import { object, string } from "yup";

import "./SignIn.css";

const SignIn = () => {
  const InitialValues = { userName: "", pass: "" };

  const validationSchema = object({
    userName: string().matches(
      /^[a-zA-Z0-9](?:[a-zA-Z0-9_-]{1,14}[a-zA-Z0-9])?$/,
      "Username must be 3–16 characters long, can include letters, numbers, underscores (_), and hyphens (-), but cannot start or end with a symbol."
    ),
    pass: string().matches(
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*])[A-Za-z\d!@#$%^&*]{8,20}$/,
      "Password must be 8–20 characters long and include at least one uppercase letter, one lowercase letter, one number, and one special character (!@#$%^&*). Spaces are not allowed."
    ),
  });

  return (
    <div className="">
      <Formik initialValues={InitialValues} validationSchema={validationSchema}>
        <Form>
          <Field placeholder="Username" name="userName"></Field>
          <ErrorMessage component='p' name="userName"></ErrorMessage>
          <Field placeholder="Password" name="pass" type="password"></Field>
          <ErrorMessage component='p' name="pass"></ErrorMessage>

          <button>Log in</button>
        </Form>
      </Formik>
      <p>Don't have an account?</p>
      <button>Sign up</button>
    </div>
  );
};

export default SignIn;
